'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const N = Number(input[0]);
const Q = Number(input[1]);

let grid = Array.from({ length: N }, (_, i) =>
  Array.from(input[i + 2], Number)
);

for (let step = 0; step < Q; step++) {
  const next = Array.from({ length: N }, () => new Array(N).fill(0));

  for (let r = 0; r < N; r++) {
    for (let c = 0; c < N; c++) {
      let neighbors = 0;

      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if (dr === 0 && dc === 0) continue;
          const nr = r + dr;
          const nc = c + dc;
          if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
            neighbors += grid[nr][nc];
          }
        }
      }

      next[r][c] = neighbors === 3 || (grid[r][c] === 1 && neighbors === 2) ? 1 : 0;
    }
  }

  grid = next;
}

console.log(grid.map(row => row.join('')).join('\n'));
